    @EventHandler( payloadType=UpdatePaymentEvent.class )
    public void handle( UpdatePaymentEvent event) {
    	LOGGER.info("handling UpdatePaymentEvent - " + event );
    	
	    Payment entity = new Payment();
            entity.setPaymentId( event.getPaymentId() );
            entity.setPaymentNumber( event.getPaymentNumber() );
            entity.setAmount( event.getAmount() );
            entity.setPaymentDate( event.getPaymentDate() );
            entity.setInvoice( event.getInvoice() );
            entity.setPayer( event.getPayer() );
            entity.setMethod( event.getMethod() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindPayment( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllPayment( entity );        
    }
    
